"""Deterministische evaluators voor fase A (dossieranalyse zonder juridisch oordeel).

Elke evaluator toetst één regel uit fase-a/beoordelingsregels.md en geeft een
Langfuse-Evaluation met een reden in `comment`. Ze lezen de uitvoer (volgens
fase-a/uitvoercontract.json), de dossierstukken uit de input en de referentie.
"""

import json
import re
from pathlib import Path
from typing import Any, Iterator

from jsonschema import Draft202012Validator
from ._evaluation import Evaluation

CONTRACT = json.loads((Path(__file__).parent / "uitvoercontract.json").read_text(encoding="utf-8"))
VALIDATOR = Draft202012Validator(CONTRACT)

# Woorden die een juridisch oordeel geven. Ze komen in de invoerstukken van deze
# dossiers niet voor (alleen in de beslissing op bezwaar, die de oplossing niet krijgt).
KERNOORDEEL = re.compile(
    r"\b(deels\s+)?(on)?gegrond\b|\bniet[- ]ontvankelijk|\bontvankelijk\b|\b(on)?rechtmatig|"
    r"\bbezwaar\s+(slaagt|faalt)|\bwij\s+adviseren\b|\badvies\s*:|"
    # PBI 176357: ook geen procesprognose, strategie, advies of concept.
    r"\bprognose|\bkans(en)?\s+(van\s+slagen|op\s+succes)|\braadzaam\b|\bstrategie\b|"
    r"\bwij\s+(raden|stellen\s+voor)|\b(naar\s+ons\s+oordeel|ons\s+inziens)\b|"
    r"\bconcept[- ]?(besluit|advies|motivering)",
    re.IGNORECASE,
)
# PBI 176357: geen externe zoekresultaten (wetten.nl, rechtspraak.nl, lokale regelgeving) en
# geen jurisprudentie. Mag alleen als het letterlijk in een dossierstuk staat (www.rotterdam.nl).
EXTERNE_BRON = re.compile(
    r"https?://\S+|\bwww\.[\w.-]+\w(/\S*)?|\b[\w-]+\.(nl|com|eu|org)\b(/\S*)?|\bECLI:[A-Z]{2}:\w+:\d{4}:[\w.]+|"
    r"\b(AB|JB|NJ|Gst\.?|BR|JGR)\s+\d{4}/\d+",
    re.IGNORECASE,
)
# Wetsartikel met de tekst erachter (tot het volgende artikel of einde zin): "artikel 5:21 Awb",
# "art. 10 lid 2 van de Afvalstoffenverordening". Niet hoofdlettergevoelig.
ARTIKEL = re.compile(r"\b(?:artikel|art\.)\s*(\d+(?:[:.]\d+)*[a-z]?)\b((?:(?!artikel|art\.)[^.;\n]){0,60})",
                     re.IGNORECASE)
# Woorden rond een artikelnummer die niets zeggen over welke regeling het is.
ALGEMEEN = {"lid", "sub", "onder", "van", "de", "het", "der", "en", "wet", "algemene", "eerste", "tweede", "derde",
            "vierde", "vijfde"}
REGELINGWOORD = re.compile(r"(wet|verordening|besluit|regeling|recht|beheer)$")
# Gangbare afkortingen; "artikel 5:21 Awb" telt als gevonden als het dossier de naam voluit schrijft, en andersom.
AFKORTINGEN = {
    "awb": "algemene wet bestuursrecht",
    "apv": "algemene plaatselijke verordening",
    "wm": "wet milieubeheer",
    "gemw": "gemeentewet",
    "wabo": "wet algemene bepalingen omgevingsrecht",
}
# Drempels (VOORSTEL, vast te stellen door de juristen).
MAX_TEKENS_BEVINDING = 600      # CHK-005: langer wijst op een geplakte passage i.p.v. een bevinding
GELIJKENIS_DUBBEL = 0.9         # CHK-029: zo gelijk telt als dubbel

INTERNE_INSTRUCTIES = re.compile(  # CHK-026
    r"\b(als (een )?(ai|taalmodel|assistent)|system ?prompt|uitvoercontract|json|"
    r"ik ben een|as an ai|language model)\b|```|document_id",
    re.IGNORECASE,
)
PLACEHOLDER = re.compile(  # CHK-028
    r"\[[^\]]{0,40}\]|\{\{.*?\}\}|<[a-z_ ]{2,30}>|\b(todo|tbd|xxx+|lorem ipsum|placeholder|invullen)\b",
    re.IGNORECASE,
)
ONAF = re.compile(r"(,|:|;|\.\.\.|…|\s-|\(|\b(en|of|de|het|een|van|met|dat))\s*$", re.IGNORECASE)  # CHK-027
NL = {"de", "het", "een", "en", "van", "is", "dat", "op", "te", "in", "voor", "niet", "met", "zijn", "aan", "bij", "door"}
EN = {"the", "a", "and", "of", "is", "that", "on", "to", "in", "for", "not", "with", "are", "by", "this", "was"}

MAANDEN = {m: i for i, m in enumerate(
    ["januari", "februari", "maart", "april", "mei", "juni", "juli", "augustus",
     "september", "oktober", "november", "december"], start=1)}
# Engels, want dossiers bevatten doorgestuurde mails ("Verzonden: Monday, November 4, 2024").
MAANDEN |= {m: i for i, m in enumerate(
    ["january", "february", "march", "april", "may", "june", "july", "august",
     "september", "october", "november", "december"], start=1)}
DATUM = re.compile(
    r"\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})\b|\b(\d{4})-(\d{2})-(\d{2})\b|"
    r"\b(\d{1,2})\s+(" + "|".join(MAANDEN) + r")\s+(\d{4})\b|"
    r"\b(" + "|".join(MAANDEN) + r")\s+(\d{1,2}),?\s+(\d{4})\b",
    re.IGNORECASE,
)
BEDRAG = re.compile(r"(?:€|EUR|euro)\s*(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d{2}))?|(?<![\w-])(\d+)(?:,(\d{2}))?\s*euro\b",
                    re.IGNORECASE)


# --- Hulpfuncties -----------------------------------------------------------------


def lees_uitvoer(output: Any) -> tuple[dict | None, list[str]]:
    if isinstance(output, str):
        try:
            output = json.loads(output)
        except ValueError:
            return None, ["uitvoer is geen geldige JSON"]
    if not isinstance(output, dict):
        return None, ["uitvoer is geen object"]
    fouten = [f"{'/'.join(map(str, e.absolute_path)) or '(root)'}: {e.message}"
              for e in sorted(VALIDATOR.iter_errors(output), key=lambda e: list(e.absolute_path))]
    return output, fouten


def bevindingen(uitvoer: dict) -> Iterator[tuple[str, dict]]:
    """Alle bevindingen met een document_id, met hun plek in de uitvoer."""
    for sectie in ("bezwaargronden", "feiten", "partijstandpunten", "tijdlijn"):
        for i, b in enumerate(uitvoer.get(sectie) or []):
            if isinstance(b, dict):
                yield f"{sectie}[{i}]", b
    pb = uitvoer.get("primair_besluit") or {}
    for sectie in ("genoemde_grondslagen", "bedragen", "datums"):
        for i, b in enumerate(pb.get(sectie) or []):
            if isinstance(b, dict):
                yield f"primair_besluit.{sectie}[{i}]", b


def teksten(waarde: Any) -> Iterator[str]:
    """Alle tekstwaarden, zonder document_id's (die zijn een verwijzing, geen inhoud)."""
    if isinstance(waarde, str):
        yield waarde
    elif isinstance(waarde, dict):
        for k, v in waarde.items():
            if k != "document_id":
                yield from teksten(v)
    elif isinstance(waarde, list):
        for v in waarde:
            yield from teksten(v)


def normaal(tekst: str) -> str:
    return " ".join(tekst.lower().replace("art.", "artikel").split())


def datums(tekst: str) -> set[str]:
    uit = set()
    for m in DATUM.finditer(tekst):
        if m.group(3):
            d, mnd, j = int(m.group(1)), int(m.group(2)), int(m.group(3))
        elif m.group(4):
            j, mnd, d = int(m.group(4)), int(m.group(5)), int(m.group(6))
        elif m.group(7):
            d, mnd, j = int(m.group(7)), MAANDEN[m.group(8).lower()], int(m.group(9))
        else:
            d, mnd, j = int(m.group(11)), MAANDEN[m.group(10).lower()], int(m.group(12))
        if 1 <= d <= 31 and 1 <= mnd <= 12:
            uit.add(f"{j:04d}-{mnd:02d}-{d:02d}")
    return uit


def bedragen(tekst: str) -> set[int]:
    """Bedragen in centen."""
    uit = set()
    for m in BEDRAG.finditer(tekst):
        euro, cent = (m.group(1), m.group(2)) if m.group(1) else (m.group(3), m.group(4))
        uit.add(int(euro.replace(".", "")) * 100 + int(cent or 0))
    return uit


def _fail_bij_ongeldige_uitvoer(naam: str, output) -> tuple[dict | None, Evaluation | None]:
    uitvoer, fouten = lees_uitvoer(output)
    if uitvoer is None or fouten:
        return None, Evaluation(name=naam, value=False, data_type="BOOLEAN",
                                comment="uitvoer volgt het contract niet; zie uitvoerformaat")
    return uitvoer, None


# --- Evaluators -------------------------------------------------------------------


def uitvoerformaat(*, output, **kwargs) -> Evaluation:
    """Uitvoer is geldige JSON volgens fase-a/uitvoercontract.json."""
    _, fouten = lees_uitvoer(output)
    return Evaluation(name="a_uitvoerformaat", value=not fouten, data_type="BOOLEAN",
                      comment="volgt het uitvoercontract" if not fouten else "; ".join(fouten[:5]))


def geen_kernoordeel(*, input, output, **kwargs) -> Evaluation:
    """Non-negotiable: geen juridisch oordeel (gegrond, ontvankelijk, rechtmatig, advies)."""
    bronnen = [normaal(d["tekst"]) for d in input["documenten"]]
    gevonden = []
    for t in teksten(output):
        for m in KERNOORDEEL.finditer(t):
            # Een letterlijk citaat uit een dossierstuk is geen oordeel van de assistent.
            if not any(normaal(t) in b for b in bronnen):
                gevonden.append(m.group(0))
    return Evaluation(name="a_geen_kernoordeel", value=not gevonden, data_type="BOOLEAN",
                      comment="geen juridisch oordeel" if not gevonden else "oordeel: " + ", ".join(sorted(set(gevonden))))


def bron_bestaat(*, input, output, **kwargs) -> Evaluation:
    """Non-negotiable: geen verzonnen bronnen. Elk document_id bestaat in het dossier."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_bron_bestaat", output)
    if fout:
        return fout
    bestaand = {d["id"] for d in input["documenten"]}
    ids = [(plek, b["document_id"]) for plek, b in bevindingen(uitvoer)]
    ids += [(f"documenten[{i}]", d["document_id"]) for i, d in enumerate(uitvoer["documenten"])]
    if uitvoer["primair_besluit"].get("document_id"):
        ids.append(("primair_besluit", uitvoer["primair_besluit"]["document_id"]))
    # Een datum uit het zaaksysteem (registratie, start) heeft in de tijdlijn als bron "zaaksysteem".
    zaaksysteem = lambda plek, i: i == "zaaksysteem" and plek.startswith("tijdlijn[") and input.get("zaak")
    verzonnen = [f"{plek}: {i}" for plek, i in ids if i not in bestaand and not zaaksysteem(plek, i)]
    return Evaluation(name="a_bron_bestaat", value=not verzonnen, data_type="BOOLEAN",
                      comment="alle bronnen bestaan" if not verzonnen else "bestaan niet: " + "; ".join(verzonnen[:10]))


def bron_bij_bevinding(*, output, **kwargs) -> Evaluation:
    """Non-negotiable: geen bewering zonder bron. Elke bevinding heeft een niet-leeg document_id."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_bron_bij_bevinding", output)
    if fout:
        return fout
    zonder = [plek for plek, b in bevindingen(uitvoer) if not str(b.get("document_id") or "").strip()]
    return Evaluation(name="a_bron_bij_bevinding", value=not zonder, data_type="BOOLEAN",
                      comment="elke bevinding heeft een bron" if not zonder else "zonder bron: " + ", ".join(zonder[:10]))


def grondslagen_letterlijk(*, input, output, expected_output, **kwargs) -> list[Evaluation]:
    """Non-negotiable: geen verkeerde grondslag. Alle genoemde grondslagen overgenomen, elk letterlijk uit de bron."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_grondslagen_letterlijk", output)
    if fout:
        return [fout]
    verwacht = expected_output["primair_besluit"]["genoemde_grondslagen"]
    gegeven = uitvoer["primair_besluit"]["genoemde_grondslagen"]
    tekst_per_doc = {d["id"]: normaal(d["tekst"]) for d in input["documenten"]}
    gemist = [g for g in verwacht if not any(normaal(g) in normaal(x["tekst"]) for x in gegeven)]
    niet_in_bron = [x["tekst"] for x in gegeven if normaal(x["tekst"]) not in tekst_per_doc.get(x["document_id"], "")]
    redenen = ([f"gemist: {', '.join(gemist)}"] if gemist else []) + \
              ([f"niet letterlijk in de bron: {', '.join(niet_in_bron)}"] if niet_in_bron else [])
    gevonden = len(verwacht) - len(gemist)
    return [
        Evaluation(name="a_grondslagen_letterlijk", value=not redenen, data_type="BOOLEAN",
                   comment="alle grondslagen letterlijk overgenomen" if not redenen else "; ".join(redenen)),
        Evaluation(name="a_grondslagen_recall", value=gevonden / len(verwacht) if verwacht else 1.0,
                   comment=f"{gevonden}/{len(verwacht)}", metadata={"gevonden": gevonden, "verwacht": len(verwacht)}),
    ]


def waarden_in_bron(*, input, output, **kwargs) -> Evaluation:
    """Non-negotiable: niets invullen wat ontbreekt. Elke datum en elk bedrag in de uitvoer staat in het dossier."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_waarden_in_bron", output)
    if fout:
        return fout
    # Stukken plus wat het zaaksysteem levert: zaakgegevens en per stuk type en datum.
    bron = list(teksten(input))
    uit = list(teksten({k: v for k, v in uitvoer.items() if k != "documenten"}))
    # Per tekstveld, zodat een jaartal en een bedrag uit twee velden niet samen één bedrag worden.
    bron_datums, bron_bedragen = set().union(*map(datums, bron)), set().union(*map(bedragen, bron))
    uit_datums, uit_bedragen = set().union(*map(datums, uit)), set().union(*map(bedragen, uit))
    verzonnen = sorted(uit_datums - bron_datums) + [f"€ {c // 100},{c % 100:02d}" for c in sorted(uit_bedragen - bron_bedragen)]
    return Evaluation(name="a_waarden_in_bron", value=not verzonnen, data_type="BOOLEAN",
                      comment="alle datums en bedragen staan in het dossier" if not verzonnen
                      else "niet in het dossier: " + ", ".join(verzonnen[:10]))


def geen_externe_bronnen(*, input, output, **kwargs) -> Evaluation:
    """Non-negotiable: geen externe zoekresultaten of jurisprudentie (URL, ECLI, vindplaats), tenzij uit het dossier."""
    bronnen = [normaal(d["tekst"]) for d in input["documenten"]]
    gevonden = sorted({m.group(0) for t in teksten(output) for m in EXTERNE_BRON.finditer(t)
                       if not any(normaal(m.group(0)) in b for b in bronnen)})
    return Evaluation(name="a_geen_externe_bronnen", value=not gevonden, data_type="BOOLEAN",
                      comment="geen externe bronnen" if not gevonden else "niet uit het dossier: " + ", ".join(gevonden[:10]))


def voluit(tekst: str) -> str:
    """Kleine letters, afkortingen voluit: "Awb" wordt "algemene wet bestuursrecht"."""
    tekst = tekst.lower()
    for afk, naam in AFKORTINGEN.items():
        tekst = re.sub(rf"\b{afk}\b", naam, tekst)
    return tekst


def regeling_kern(staart: str) -> str | None:
    """Het kenmerkende woord van de regeling achter een artikelnummer, of None als er geen regeling genoemd wordt.

    "Wet milieubeheer" -> "milieubeheer", "Awb" -> "bestuursrecht", "is overtreden" -> None.
    """
    for woord in re.findall(r"[^\W\d_][\w-]*", staart):
        if len(woord) == 1 or woord.lower() in ALGEMEEN:
            continue
        if woord.lower() in AFKORTINGEN:
            return next(w for w in AFKORTINGEN[woord.lower()].split() if w not in ALGEMEEN)
        return woord.lower() if woord[0].isupper() or REGELINGWOORD.search(woord.lower()) else None
    return None


def wetsartikelen_in_dossier(*, input, output, **kwargs) -> Evaluation:
    """Non-negotiable: geen ongevalideerde wetgeving. Elk genoemd artikel (met regeling) staat in een dossierstuk."""
    bronnen = [voluit(d["tekst"]) for d in input["documenten"]]
    gevonden = set()
    for t in teksten(output):
        for m in ARTIKEL.finditer(t):
            nummer, kern = m.group(1), regeling_kern(m.group(2))
            artikel = re.compile(rf"\b(?:artikel|art\.)\s*{re.escape(nummer)}(?![\w:])")
            # Zelfde artikelnummer in een stuk, en (als er een regeling bij staat) die regeling er vlak achter.
            if not any(kern is None or kern in b[a.end():a.end() + 80] for b in bronnen for a in artikel.finditer(b)):
                gevonden.add(f"artikel {nummer}" + (f" ({kern})" if kern else ""))
    gevonden = sorted(gevonden)
    return Evaluation(name="a_wetsartikelen_in_dossier", value=not gevonden, data_type="BOOLEAN",
                      comment="alle genoemde artikelen staan in het dossier" if not gevonden
                      else "niet in het dossier: " + ", ".join(gevonden[:10]))


def documentoverzicht(*, input, output, **kwargs) -> Evaluation:
    """Sectie 2: elk aangeleverd document precies één keer, met de juiste naam."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_documentoverzicht", output)
    if fout:
        return fout
    verwacht = {d["id"]: d["naam"] for d in input["documenten"]}
    gegeven = [d["document_id"] for d in uitvoer["documenten"]]
    problemen = [f"ontbreekt: {i}" for i in verwacht if i not in gegeven]
    problemen += [f"dubbel: {i}" for i in sorted({i for i in gegeven if gegeven.count(i) > 1})]
    problemen += [f"naam {d['document_id']}: {d['naam']!r} i.p.v. {verwacht[d['document_id']]!r}"
                  for d in uitvoer["documenten"] if d["document_id"] in verwacht and d["naam"] != verwacht[d["document_id"]]]
    return Evaluation(name="a_documentoverzicht", value=not problemen, data_type="BOOLEAN",
                      comment="documentoverzicht compleet" if not problemen else "; ".join(problemen[:10]))


# Zo zegt de analyse dat het zaaksysteem iets niet kent; dat is geen bedacht gegeven.
ONBEKEND = re.compile(r"^\s*(niet beschikbaar|onbekend|niet bekend|geen\b.*\bgeregistreerd|nog niet afgesloten|-)?\s*$",
                      re.IGNORECASE)


def _zelfde_waarde(verwacht: str, gegeven: str) -> bool:
    if datums(verwacht):
        return datums(verwacht) == datums(gegeven)
    return " ".join(verwacht.lower().split()) == " ".join(gegeven.lower().split())


def zaakoverzicht(*, output, expected_output, **kwargs) -> Evaluation:
    """Sectie 1: elk veld uit het zaaksysteem staat erin met dezelfde waarde; wat het zaaksysteem
    niet kent, is niet ingevuld."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_zaakoverzicht", output)
    if fout:
        return fout
    gegeven = uitvoer["zaakoverzicht"]
    problemen = []
    for veld, waarde in (expected_output.get("zaakoverzicht") or {}).items():
        g = gegeven.get(veld)
        if waarde is None:
            if g is not None and not ONBEKEND.match(g):
                problemen.append(f"{veld}: {g!r}, maar het zaaksysteem kent geen waarde")
        elif g is None or ONBEKEND.match(g):
            problemen.append(f"{veld}: ontbreekt (zaaksysteem: {waarde!r})")
        elif not _zelfde_waarde(str(waarde), g):
            problemen.append(f"{veld}: {g!r} i.p.v. {waarde!r}")
    return Evaluation(name="a_zaakoverzicht", value=not problemen, data_type="BOOLEAN",
                      comment="zaakgegevens kloppen met het zaaksysteem" if not problemen else "; ".join(problemen))


def _bevindingteksten(uitvoer: dict) -> Iterator[tuple[str, str]]:
    for plek, b in bevindingen(uitvoer):
        for k in ("tekst", "gebeurtenis"):
            if isinstance(b.get(k), str):
                yield plek, b[k]
    pb = uitvoer.get("primair_besluit") or {}
    for k in ("besloten", "aanleiding"):
        if isinstance(pb.get(k), str):
            yield f"primair_besluit.{k}", pb[k]


def geen_lege_secties(*, output, expected_output, **kwargs) -> Evaluation:
    """CHK-004: documenten, tijdlijn en (als het dossier er een heeft) het primaire besluit zijn niet leeg."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_geen_lege_secties", output)
    if fout:
        return fout
    leeg = [s for s in ("documenten", "tijdlijn") if not uitvoer[s]]
    if expected_output["primair_besluit"].get("document_id") and not uitvoer["primair_besluit"].get("document_id"):
        leeg.append("primair_besluit.document_id")
    return Evaluation(name="a_geen_lege_secties", value=not leeg, data_type="BOOLEAN",
                      comment="verplichte secties gevuld" if not leeg else "leeg: " + ", ".join(leeg))


def geen_lange_bevinding(*, output, **kwargs) -> Evaluation:
    """CHK-005 (waarschuwing): geen bevinding langer dan MAX_TEKENS_BEVINDING."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_geen_lange_bevinding", output)
    if fout:
        return fout
    lang = [f"{plek} ({len(x)} tekens)" for plek, x in _bevindingteksten(uitvoer) if len(x) > MAX_TEKENS_BEVINDING]
    return Evaluation(name="a_geen_lange_bevinding", value=not lang, data_type="BOOLEAN",
                      comment=f"alle bevindingen ≤ {MAX_TEKENS_BEVINDING} tekens" if not lang else "te lang: " + ", ".join(lang[:5]))


def _patroon_check(naam: str, patroon: re.Pattern, uitleg: str, input, output) -> Evaluation:
    uitvoer, fout = _fail_bij_ongeldige_uitvoer(naam, output)
    if fout:
        return fout
    bronnen = [normaal(d["tekst"]) for d in input["documenten"]]
    treffers = [f"{plek}: {m.group(0)!r}" for plek, x in _bevindingteksten(uitvoer)
                for m in patroon.finditer(x) if not any(normaal(x) in b for b in bronnen)]
    return Evaluation(name=naam, value=not treffers, data_type="BOOLEAN",
                      comment=f"geen {uitleg}" if not treffers else "; ".join(treffers[:5]))


def geen_interne_instructies(*, input, output, **kwargs) -> Evaluation:
    """CHK-026: geen sporen van prompt of technische instructies in de tekst."""
    return _patroon_check("a_geen_interne_instructies", INTERNE_INSTRUCTIES, "interne instructies", input, output)


def geen_placeholders(*, input, output, **kwargs) -> Evaluation:
    """CHK-028: geen [ ], {{ }}, <veld>, TODO, lorem ipsum."""
    return _patroon_check("a_geen_placeholders", PLACEHOLDER, "placeholders", input, output)


def geen_onafgemaakte_tekst(*, input, output, **kwargs) -> Evaluation:
    """CHK-027: geen bevinding die halverwege ophoudt."""
    return _patroon_check("a_geen_onafgemaakte_tekst", ONAF, "onafgemaakte tekst", input, output)


def geen_dubbele_bevindingen(*, output, **kwargs) -> Evaluation:
    """CHK-029 (waarschuwing): binnen een sectie geen (bijna) gelijke bevindingen."""
    from difflib import SequenceMatcher
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_geen_dubbele_bevindingen", output)
    if fout:
        return fout
    per_sectie: dict[str, list[tuple[str, str]]] = {}
    for plek, x in _bevindingteksten(uitvoer):
        per_sectie.setdefault(plek.split("[")[0], []).append((plek, normaal(x)))
    dubbel = []
    for lijst in per_sectie.values():
        for i, (p1, a) in enumerate(lijst):
            for p2, b in lijst[i + 1:]:
                if a and SequenceMatcher(None, a, b).ratio() >= GELIJKENIS_DUBBEL:
                    dubbel.append(f"{p1} ≈ {p2}")
    return Evaluation(name="a_geen_dubbele_bevindingen", value=not dubbel, data_type="BOOLEAN",
                      comment="geen dubbele bevindingen" if not dubbel else "; ".join(dubbel[:5]))


def taal_nederlands(*, output, **kwargs) -> Evaluation:
    """CHK-030 (waarschuwing): de bevindingen zijn Nederlands, niet Engels."""
    uitvoer, fout = _fail_bij_ongeldige_uitvoer("a_taal_nederlands", output)
    if fout:
        return fout
    woorden = re.findall(r"[a-zà-ÿ]+", " ".join(x for _, x in _bevindingteksten(uitvoer)).lower())
    nl, en = sum(w in NL for w in woorden), sum(w in EN for w in woorden)
    return Evaluation(name="a_taal_nederlands", value=nl >= en, data_type="BOOLEAN",
                      comment=f"Nederlandse functiewoorden {nl}, Engelse {en}")


def grondslagen_recall_totaal(*, item_results, **kwargs) -> Evaluation:
    gevonden = verwacht = 0
    for r in item_results:
        for e in r.evaluations:
            if e.name == "a_grondslagen_recall":
                gevonden += e.metadata["gevonden"]; verwacht += e.metadata["verwacht"]
    return Evaluation(name="a_grondslagen_recall_totaal", value=gevonden / verwacht if verwacht else 0.0,
                      comment=f"{gevonden}/{verwacht} genoemde grondslagen overgenomen")


def non_negotiables_geslaagd(*, item_results, **kwargs) -> Evaluation:
    """Aandeel dossiers waarin alle blokkerende checks slagen."""
    geslaagd = sum(all(e.value for e in r.evaluations if e.name in NON_NEGOTIABLES) for r in item_results)
    return Evaluation(name="a_non_negotiables_geslaagd", value=geslaagd / len(item_results) if item_results else 0.0,
                      comment=f"{geslaagd}/{len(item_results)} dossiers zonder blokkerende fout")


